-- Clean bootstrap 021: transactional RPCs, role/rate administration and comprehensive audit.
CREATE OR REPLACE FUNCTION public.validated_exchange_rate(p_currency_code text,p_requested numeric DEFAULT NULL) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE active_rate numeric; BEGIN IF p_currency_code='CDF' THEN IF p_requested IS NOT NULL AND abs(p_requested-1)>0.0001 THEN RAISE EXCEPTION 'CDF exchange rate must be 1'; END IF; RETURN 1; ELSIF p_currency_code<>'USD' THEN RAISE EXCEPTION 'Unsupported currency'; END IF; SELECT rate INTO active_rate FROM public.exchange_rates WHERE base_currency='USD' AND quote_currency='CDF' AND is_active AND valid_from<=now() AND (valid_until IS NULL OR valid_until>now()) ORDER BY valid_from DESC LIMIT 1; IF active_rate IS NULL THEN RAISE EXCEPTION 'No active USD/CDF rate'; END IF; IF p_requested IS NOT NULL AND abs(p_requested-active_rate)>greatest(.0001,active_rate*.001) THEN RAISE EXCEPTION 'Stale or manipulated exchange rate'; END IF; RETURN active_rate; END $$;
CREATE OR REPLACE FUNCTION public.update_exchange_rate(p_base_currency text,p_quote_currency text,p_new_rate numeric) RETURNS public.exchange_rates LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.exchange_rates; old jsonb; BEGIN PERFORM public.assert_admin(); IF p_new_rate<=0 OR p_base_currency=p_quote_currency OR p_base_currency NOT IN('CDF','USD') OR p_quote_currency NOT IN('CDF','USD') THEN RAISE EXCEPTION 'Invalid exchange rate'; END IF; SELECT to_jsonb(e) INTO old FROM public.exchange_rates e WHERE base_currency=p_base_currency AND quote_currency=p_quote_currency AND is_active FOR UPDATE; UPDATE public.exchange_rates SET is_active=false,valid_until=now() WHERE base_currency=p_base_currency AND quote_currency=p_quote_currency AND is_active; INSERT INTO public.exchange_rates(base_currency,quote_currency,rate,created_by) VALUES(p_base_currency,p_quote_currency,p_new_rate,auth.uid()) RETURNING * INTO result; PERFORM public.write_audit_log('update_exchange_rate','exchange_rates',result.id,old,to_jsonb(result)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.update_user_role(p_target_user uuid,p_new_role uuid) RETURNS public.user_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_profile public.user_profiles; result public.user_profiles; BEGIN PERFORM public.assert_admin(); SELECT * INTO STRICT old_profile FROM public.user_profiles WHERE id=p_target_user FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.roles WHERE id=p_new_role) THEN RAISE EXCEPTION 'Role not found'; END IF; PERFORM set_config('app.role_change_rpc','on',true); UPDATE public.user_profiles SET role_id=p_new_role WHERE id=p_target_user RETURNING * INTO result; PERFORM public.write_audit_log('update_user_role','user_profiles',p_target_user,jsonb_build_object('old_role_id',old_profile.role_id),jsonb_build_object('new_role_id',result.role_id,'changed_by',auth.uid())); INSERT INTO public.security_events(event_type,user_id,success,metadata) VALUES('role_changed',p_target_user,true,jsonb_build_object('old_role_id',old_profile.role_id,'new_role_id',result.role_id,'changed_by',auth.uid())); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.update_user_status(p_target_user uuid,p_is_active boolean) RETURNS public.user_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.user_profiles; old_status boolean; BEGIN PERFORM public.assert_admin(); SELECT is_active INTO STRICT old_status FROM public.user_profiles WHERE id=p_target_user FOR UPDATE; IF p_target_user=auth.uid() AND NOT p_is_active THEN RAISE EXCEPTION 'Administrators cannot deactivate their own active session'; END IF; PERFORM set_config('app.role_change_rpc','on',true); UPDATE public.user_profiles SET is_active=p_is_active WHERE id=p_target_user RETURNING * INTO result; PERFORM public.write_audit_log('update_user_status','user_profiles',p_target_user,jsonb_build_object('is_active',old_status),jsonb_build_object('is_active',p_is_active)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.provision_invited_user_profile(p_target_user uuid,p_email text,p_full_name text,p_role_name text,p_phone text DEFAULT NULL,p_company_name text DEFAULT NULL,p_actor uuid DEFAULT NULL) RETURNS public.user_profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE selected_role public.roles; result public.user_profiles; BEGIN SELECT * INTO STRICT selected_role FROM public.roles WHERE name=p_role_name; PERFORM set_config('app.role_change_rpc','on',true); INSERT INTO public.user_profiles(id,email,full_name,role_id,role,sector,phone,company_name,is_active,must_change_password) VALUES(p_target_user,lower(p_email),COALESCE(NULLIF(p_full_name,''),split_part(p_email,'@',1)),selected_role.id,selected_role.name,selected_role.sector,p_phone,p_company_name,true,true) ON CONFLICT(id) DO UPDATE SET email=EXCLUDED.email,full_name=EXCLUDED.full_name,role_id=EXCLUDED.role_id,phone=EXCLUDED.phone,company_name=EXCLUDED.company_name,is_active=true,must_change_password=true RETURNING * INTO result; PERFORM public.write_audit_log('provision_invited_user','user_profiles',p_target_user,NULL,jsonb_build_object('role_id',selected_role.id,'role',selected_role.name),p_actor); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.provision_invited_user_profile(uuid,text,text,text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.provision_invited_user_profile(uuid,text,text,text,text,text,uuid) TO service_role;
CREATE SEQUENCE IF NOT EXISTS public.sales_order_number_seq;
CREATE OR REPLACE FUNCTION public.create_order_with_items(p_customer_id uuid,p_items jsonb,p_notes text DEFAULT NULL,p_currency text DEFAULT 'CDF',p_exchange_rate numeric DEFAULT 1,p_payment_type text DEFAULT 'cash',p_discount numeric DEFAULT 0) RETURNS public.sales_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.sales_orders; item jsonb; product public.products; subtotal numeric:=0; discount_amount numeric; rate numeric; max_discount numeric:=0; BEGIN IF NOT (public.is_admin() OR public.has_role('commercial_staff','client_b2b')) THEN RAISE EXCEPTION 'Role not allowed' USING ERRCODE='42501'; END IF; IF NOT public.can_read_customer(p_customer_id) THEN RAISE EXCEPTION 'Customer access denied' USING ERRCODE='42501'; END IF; IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Items required'; END IF; rate:=public.validated_exchange_rate(p_currency,p_exchange_rate); IF public.is_admin() THEN max_discount:=100; ELSE SELECT COALESCE((config_value#>>'{}')::numeric,10) INTO max_discount FROM public.system_configuration WHERE config_key='max_sales_discount_percent'; END IF; IF p_discount<0 OR p_discount>max_discount THEN RAISE EXCEPTION 'Discount exceeds role limit'; END IF; FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP SELECT * INTO product FROM public.products WHERE id=(item->>'product_id')::uuid AND is_active FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Product not found'; END IF; IF (item->>'quantity')::integer<=0 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; subtotal:=subtotal+product.unit_price*(item->>'quantity')::integer; END LOOP; discount_amount:=round(subtotal*p_discount/100,2); INSERT INTO public.sales_orders(order_number,customer_id,sales_rep_id,created_by,subtotal,discount_amount,total_amount,currency,exchange_rate,payment_type,notes) VALUES('SO-'||to_char(now(),'YYYYMMDD')||'-'||lpad(nextval('public.sales_order_number_seq')::text,6,'0'),p_customer_id,CASE WHEN public.has_role('commercial_staff') THEN auth.uid() END,auth.uid(),subtotal,discount_amount,subtotal-discount_amount,p_currency,rate,p_payment_type,p_notes) RETURNING * INTO result; FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP SELECT * INTO STRICT product FROM public.products WHERE id=(item->>'product_id')::uuid; INSERT INTO public.order_items(order_id,product_id,quantity,unit_price,line_total) VALUES(result.id,product.id,(item->>'quantity')::integer,product.unit_price,product.unit_price*(item->>'quantity')::integer); END LOOP; PERFORM public.write_audit_log('create_order','sales_orders',result.id,NULL,to_jsonb(result)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.adjust_stock(p_product_id uuid,p_warehouse_id uuid,p_quantity_delta integer,p_reason text,p_reference_type text DEFAULT NULL,p_reference_id uuid DEFAULT NULL,p_notes text DEFAULT NULL) RETURNS public.stock_movements LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_qty integer; result public.stock_movements; movement text; BEGIN IF NOT (public.is_admin() OR public.has_role('warehouse_staff')) THEN RAISE EXCEPTION 'Role not allowed' USING ERRCODE='42501'; END IF; IF public.has_role('warehouse_staff') AND p_warehouse_id<>(SELECT warehouse_id FROM public.user_profiles WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Warehouse access denied'; END IF; SELECT COALESCE(quantity,0) INTO current_qty FROM public.inventory_stock WHERE product_id=p_product_id AND warehouse_id=p_warehouse_id FOR UPDATE; IF current_qty+p_quantity_delta<0 THEN RAISE EXCEPTION 'Insufficient stock'; END IF; movement:=CASE WHEN p_quantity_delta>0 THEN 'in' WHEN p_quantity_delta<0 THEN 'out' ELSE 'adjustment' END; INSERT INTO public.stock_movements(product_id,warehouse_id,movement_type,quantity,reference_type,reference_id,notes,created_by) VALUES(p_product_id,p_warehouse_id,movement,abs(p_quantity_delta),COALESCE(p_reference_type,p_reason),p_reference_id,p_notes,auth.uid()) RETURNING * INTO result; PERFORM public.write_audit_log('adjust_stock','stock_movements',result.id,NULL,to_jsonb(result)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.confirm_delivery(p_delivery_id uuid,p_signature_url text DEFAULT NULL,p_notes text DEFAULT NULL) RETURNS public.deliveries LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.deliveries; BEGIN SELECT * INTO STRICT result FROM public.deliveries WHERE id=p_delivery_id FOR UPDATE; IF NOT(public.is_admin() OR public.has_role('delivery_agent') AND result.delivery_agent_id=auth.uid()) THEN RAISE EXCEPTION 'Delivery access denied'; END IF; IF result.status<>'in_transit' OR (SELECT order_status FROM public.sales_orders WHERE id=result.order_id)<>'shipped' THEN RAISE EXCEPTION 'Invalid delivery transition'; END IF; UPDATE public.deliveries SET status='delivered',actual_delivery_time=now(),signature_url=COALESCE(NULLIF(p_signature_url,''),deliveries.signature_url),notes=COALESCE(p_notes,deliveries.notes),updated_at=now() WHERE id=p_delivery_id RETURNING * INTO result; UPDATE public.sales_orders SET order_status='delivered',updated_at=now() WHERE id=result.order_id; INSERT INTO public.workflow_transitions(entity_type,entity_id,from_status,to_status,changed_by) VALUES('delivery',result.id,'in_transit','delivered',auth.uid()); PERFORM public.write_audit_log('confirm_delivery','deliveries',result.id,jsonb_build_object('status','in_transit'),to_jsonb(result)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.record_payment(p_invoice_id uuid,p_amount numeric,p_payment_method text,p_reference_number text DEFAULT NULL,p_notes text DEFAULT NULL,p_currency text DEFAULT 'CDF') RETURNS public.payments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invoice public.invoices; result public.payments; new_paid numeric; BEGIN IF NOT(public.is_admin() OR public.has_role('comptable')) THEN RAISE EXCEPTION 'Role not allowed'; END IF; SELECT * INTO STRICT invoice FROM public.invoices WHERE id=p_invoice_id FOR UPDATE; IF p_currency<>invoice.currency OR p_amount<=0 OR invoice.amount_paid+p_amount>invoice.total_amount THEN RAISE EXCEPTION 'Invalid payment'; END IF; INSERT INTO public.payments(invoice_id,amount,payment_method,reference_number,notes,currency,created_by) VALUES(p_invoice_id,p_amount,p_payment_method,p_reference_number,p_notes,p_currency,auth.uid()) RETURNING * INTO result; new_paid:=invoice.amount_paid+p_amount; UPDATE public.invoices SET amount_paid=new_paid,payment_status=CASE WHEN new_paid=total_amount THEN 'paid' ELSE 'partial' END WHERE id=p_invoice_id; UPDATE public.sales_orders SET payment_status=CASE WHEN new_paid=invoice.total_amount THEN 'paid' ELSE 'partial' END WHERE id=invoice.order_id; PERFORM public.write_audit_log('record_payment','payments',result.id,NULL,to_jsonb(result)); RETURN result; END $$;

CREATE OR REPLACE FUNCTION public.get_product_costs() RETURNS TABLE(id uuid,sku text,name text,cost_price numeric,currency text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT(public.is_admin() OR public.has_role('comptable')) THEN RAISE EXCEPTION 'Finance role required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT p.id,p.sku,p.name,p.cost_price,p.currency FROM public.products p; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['roles','user_profiles','product_categories','products','warehouse_locations','customers','sales_orders','order_items','inventory_stock','stock_movements','invoices','payments','expenses','expense_approval_history','delivery_routes','deliveries','suppliers','purchases','purchase_order_items','document_attachments','notification_templates','workflow_transitions','exchange_rates','cash_registers','cash_movements','bank_accounts','bank_transactions','accounting_entries','support_tickets','system_configuration','user_permissions','security_thresholds','security_anomalies','automation_rules','rule_conditions','rule_actions','forensic_events','forensic_export_templates','forensic_export_history','investigations','investigation_tasks','investigation_evidence'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS audit_%I ON public.%I',t,t); EXECUTE format('CREATE TRIGGER audit_%I AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_row_change()',t,t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.update_user_status(uuid,boolean),public.update_user_role(uuid,uuid),public.update_exchange_rate(text,text,numeric),public.create_order_with_items(uuid,jsonb,text,text,numeric,text,numeric),public.adjust_stock(uuid,uuid,integer,text,text,uuid,text),public.confirm_delivery(uuid,text,text),public.record_payment(uuid,numeric,text,text,text,text),public.get_product_costs() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_user_status(uuid,boolean),public.update_user_role(uuid,uuid),public.update_exchange_rate(text,text,numeric),public.create_order_with_items(uuid,jsonb,text,text,numeric,text,numeric),public.adjust_stock(uuid,uuid,integer,text,text,uuid,text),public.confirm_delivery(uuid,text,text),public.record_payment(uuid,numeric,text,text,text,text),public.get_product_costs() TO authenticated;
